.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 8px;
    transition: background-color 0.15s;
}

.channel-item:hover {
    background-color: #34373c;
}

.channel-item.active {
    background-color: #40444b;
}

.channel-info {
    flex: 1;
    min-width: 0;
}

.channel-name {
    font-weight: 500;
    font-size: 15px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.channel-desc {
    font-size: 12px;
    color: #8e9297;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.badge {
    background-color: #ed4245;
    color: #fff;
    border-radius: 10px;
    padding: 2px 6px;
    font-size: 11px;
    font-weight: 700;
    min-width: 18px;
    text-align: center;
    flex-shrink: 0;
}

@if (Reactions?.Count > 0)
{
    <div class="reaction-bar">
        @foreach (var reaction in Reactions)
        {
            <span class="reaction-badge" title="@string.Join(", ", reaction.Users)">
                @reaction.Emoji @reaction.Users.Count
            </span>
        }
    </div>
}

