+<div class="message-input">
+    <textarea @bind="Text"
+              @bind:event="oninput"
+              @onkeydown="HandleKeyDown"
+              placeholder="@Placeholder"
+              rows="1"></textarea>
+    <button class="send-btn" @onclick="Send" disabled="@string.IsNullOrWhiteSpace(Text)">
+        @ButtonLabel
+    </button>
+</div>
+
+@code {
+    [Parameter]
+    public string Placeholder { get; set; } = "Type a message…";
+
