arguments.file_text:
.message-bubble {
    padding: 8px 16px;
    position: relative;
    transition: background-color 0.1s;
}

.message-bubble:hover {
    background-color: #32353b;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author {
    font-weight: 600;
    font-size: 15px;
    color: #fff;
}

.timestamp {
    font-size: 12px;
    color: #72767d;
}

.message-content {
    font-size: 15px;
    color: #dcddde;
    line-height: 1.4;
    word-break: break-word;
}

.thread-link {
    background: none;
    border: none;
    color: #00aff4;
    font-size: 13px;
    cursor: pointer;
    padding: 4px 0;
    margin-top: 4px;
    display: block;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    display: none;
    position: absolute;
    top: -12px;
    right: 16px;
    background-color: #2f3136;
    border: 1px solid #40444b;
    border-radius: 4px;
    overflow: hidden;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.25);
}

.message-bubble:hover .message-actions {
    display: flex;
}

.message-actions button {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 13px;
    padding: 6px 10px;
    cursor: pointer;
    white-space: nowrap;
}

.message-actions button:hover {
    background-color: #40444b;
    color: #fff;
}

@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="message-list" @ref="_listRef">
    @if (IsLoadingMore)
    {
        <div class="loading-indicator">Loading older messages…</div>
    }

    @foreach (var message in Messages)
    {
        <MessageBubble Message="message"
                       ReplyCount="GetReplyCount(message.Id)"
                       OnOpenThread="OnOpenThread"
                       OnReact="OnReact" />
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<Message> Messages { get; set; } = [];

    [Parameter]
    public Dictionary<int, int> ReplyCounts { get; set; } = new();

    [Parameter]
    public bool IsLoadingMore { get; set; }

    [Parameter]
    public EventCallback<int> OnOpenThread { get; set; }

    [Parameter]
    public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    [Parameter]
    public EventCallback OnLoadMore { get; set; }

    private ElementReference _listRef;
    private IJSObjectReference? _module;
    private DotNetObjectReference<MessageList>? _dotNetRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>("import", "./js/chat.js");
            _dotNetRef = DotNetObjectReference.Create(this);
            await _module.InvokeVoidAsync("initScrollObserver", _listRef, _dotNetRef);
            await _module.InvokeVoidAsync("scrollToBottom", _listRef);
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        await OnLoadMore.InvokeAsync();
    }

    private int GetReplyCount(int messageId) =>
        ReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    public async ValueTask DisposeAsync()
    {
        _dotNetRef?.Dispose();
        if (_module is not null)
        {
            await _module.DisposeAsync();
        }
    }
}

.message-list {
    flex: 1;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 2px;
    padding: 8px 0;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #72767d;
    font-size: 13px;
}

.channel-sidebar {
    width: 240px;
    min-width: 200px;
    background-color: #2f3136;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    overflow-y: auto;
    border-right: 1px solid #202225;
    flex-shrink: 0;
}

.channel-sidebar h3 {
    padding: 16px;
    margin: 0;
    font-size: 12px;
    text-transform: uppercase;
    color: #8e9297;
    letter-spacing: 0.5px;
    font-weight: 700;
}

.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    background-color: #36393f;
    color: #dcddde;
}

.channel-header {
    padding: 12px 16px;
    border-bottom: 1px solid #40444b;
    flex-shrink: 0;
}

