toolArgs.file_text:
.message-bubble {
    padding: 8px 16px;
    position: relative;
    transition: background-color 0.1s;
}

.message-bubble:hover {
    background-color: #32353b;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author {
    font-weight: 600;
    font-size: 15px;
    color: #fff;
}

.timestamp {
    font-size: 12px;
    color: #72767d;
}

.message-content {
    font-size: 15px;
    color: #dcddde;
    line-height: 1.4;
    word-break: break-word;
}

.thread-link {
    background: none;
    border: none;
    color: #00aff4;
    font-size: 13px;
    cursor: pointer;
    padding: 4px 0;
    margin-top: 4px;
    display: block;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    display: none;
    position: absolute;
    top: -12px;
    right: 16px;
    background-color: #2f3136;
    border: 1px solid #40444b;
    border-radius: 4px;
    overflow: hidden;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.25);
}

.message-bubble:hover .message-actions {
    display: flex;
}

.message-actions button {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 13px;
    padding: 6px 10px;
    cursor: pointer;
    white-space: nowrap;
}

.message-actions button:hover {
    background-color: #40444b;
    color: #fff;
}

