.thread-panel {
    width: 340px;
    min-width: 280px;
    background-color: #36393f;
    border-left: 1px solid #40444b;
    display: flex;
    flex-direction: column;
    color: #dcddde;
    flex-shrink: 0;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #40444b;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 16px;
    font-weight: 700;
    color: #fff;
}

.close-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 18px;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    line-height: 1;
}

.close-btn:hover {
    background-color: #40444b;
    color: #fff;
}

.thread-root-message {
    padding: 12px 16px;
    background-color: #2f3136;
    border-bottom: 1px solid #40444b;
    flex-shrink: 0;
}

.thread-root-message .author {
    font-weight: 600;
    font-size: 14px;
    color: #fff;
}

.root-content {
    margin: 4px 0 0;
    font-size: 14px;
    color: #b9bbbe;
    line-height: 1.4;
}

.thread-divider {
    padding: 8px 16px;
    font-size: 12px;
    color: #72767d;
    border-bottom: 1px solid #40444b;
    flex-shrink: 0;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.thread-reply {
    padding: 8px 16px;
}

.thread-reply:hover {
    background-color: #32353b;
}

.reply-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.reply-header .author {
    font-weight: 600;
    font-size: 14px;
    color: #fff;
}

.reply-header .timestamp {
    font-size: 12px;
    color: #72767d;
}

.reply-content {
    font-size: 14px;
    color: #dcddde;
    line-height: 1.4;
}

