toolArgs.file_text:
@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="_channels"
                    ActiveChannelId="@(_selectedChannel?.Id ?? 0)"
                    OnChannelSelected="HandleChannelSelected" />

    <MessageArea ChannelName="@(_selectedChannel?.Name ?? "")"
                 ChannelDescription="@(_selectedChannel?.Description ?? "")"
                 Messages="_messages"
                 ReplyCounts="_replyCounts"
                 IsLoadingMore="_isLoadingMore"
                 OnOpenThread="HandleOpenThread"
                 OnReact="HandleReact"
                 OnLoadMore="HandleLoadMore"
                 OnSendMessage="HandleSendMessage" />

    @if (_threadOpen)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     Replies="_threadReplies"
                     OnClose="HandleCloseThread"
                     OnSendReply="HandleSendReply" />
    }
</div>

@code {
    private List<Channel> _channels = [];
    private Channel? _selectedChannel;
    private List<Message> _messages = [];
    private Dictionary<int, int> _replyCounts = new();
    private bool _isLoadingMore;
    private int _messageSkip;
    private const int PageSize = 50;

    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0]);
        }
    }

    private async Task HandleChannelSelected(Channel channel)
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
        await SelectChannel(channel);
    }

    private async Task SelectChannel(Channel channel)
    {
        _selectedChannel = channel;
        _messageSkip = 0;
        _replyCounts = new Dictionary<int, int>();
        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _messageSkip = _messages.Count;
        UpdateReplyCounts();
        await ChatService.MarkChannelReadAsync(channel.Id);

        var idx = _channels.FindIndex(c => c.Id == channel.Id);
        if (idx >= 0)
        {
            _channels[idx] = channel with { UnreadCount = 0 };
        }
    }

    private async Task HandleSendMessage(string content)
    {
        if (_selectedChannel is null) return;

        var msg = await ChatService.SendMessageAsync(_selectedChannel.Id, content, null);
        _messages.Add(msg);
        _messageSkip++;
    }

    private async Task HandleOpenThread(int rootMessageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        _threadReplies = await ChatService.GetThreadAsync(rootMessageId);
        _replyCounts[rootMessageId] = _threadReplies.Count;
        _threadOpen = true;
    }

    private void HandleCloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task HandleSendReply(string content)
    {
        if (_selectedChannel is null || _threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(
            _selectedChannel.Id, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);
        _replyCounts[_threadRootMessage.Id] = _threadReplies.Count;
    }

    private async Task HandleReact((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Refresh messages to reflect updated reactions
        if (_selectedChannel is not null)
        {
            _messages = await ChatService.GetMessagesAsync(
                _selectedChannel.Id, 0, _messageSkip);
            UpdateReplyCounts();
        }
    }

    private async Task HandleLoadMore()
    {
        if (_isLoadingMore || _selectedChannel is null) return;

        _isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(
            _selectedChannel.Id, _messageSkip, PageSize);

        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            _messageSkip += older.Count;
            UpdateReplyCounts();
        }

        _isLoadingMore = false;
    }

    private void UpdateReplyCounts()
    {
        var feedCounts = new Dictionary<int, int>();
        foreach (var msg in _messages.Where(m => m.ReplyToId.HasValue))
        {
            var rootId = msg.ReplyToId!.Value;
            feedCounts.TryGetValue(rootId, out var count);
            feedCounts[rootId] = count + 1;
        }

        foreach (var (key, value) in feedCounts)
        {
            _replyCounts.TryGetValue(key, out var existing);
            _replyCounts[key] = Math.Max(existing, value);
        }
    }
}

